mapper.sql:
WHERE s.venue_hall_id = #{condition.venueHallId}

AND s.status = 'ACTIVE'

AND NOT EXISTS (
SELECT 1

FROM v1_performance_seats ps

WHERE ps.performance_id =
#{condition.performanceId}

AND ps.seat_id = s.id
)


  AND (
  s.section_name LIKE CONCAT(
  '%',
  #{condition.keyword},
  '%'
  )

  OR s.row_name LIKE CONCAT(
  '%',
  #{condition.keyword},
  '%'
  )

  OR s.seat_number LIKE CONCAT(
  '%',
  #{condition.keyword},
  '%'
  )
  )



  AND s.floor = #{condition.floor}



  AND s.seat_type = #{condition.seatType}
